@import url('https://fonts.googleapis.com/css2?family=DM+Mono:wght@400;500&family=Manrope:wght@400;500;600;700;800&family=Unbounded:wght@500;600;700&display=swap');
:root{color-scheme:dark;--cream:#f1e7cd;--muted:#a6ad8d;--lime:#c8f19a;--green:#91c879;--orange:#f0a36f;--panel:rgba(17,29,20,.94)}*{box-sizing:border-box}html,body,#app{width:100%;height:100%;margin:0;overflow:hidden}body{background:#101a13;color:var(--cream);font-family:Manrope,system-ui,sans-serif;overscroll-behavior:none;touch-action:none}button{font:inherit;color:inherit}#app{position:relative;isolation:isolate}#game{position:absolute;inset:0;width:100%;height:100%;display:block;background:#18281c;touch-action:none}#minimap{display:block;width:100%;height:100%}.hidden{display:none!important}.hud-top{position:absolute;top:max(18px,env(safe-area-inset-top));left:max(20px,env(safe-area-inset-left));right:max(20px,env(safe-area-inset-right));display:flex;align-items:flex-start;justify-content:space-between;z-index:2;pointer-events:none}.hud-left,.hud-right{display:flex;align-items:flex-start;gap:14px}.health{display:flex;gap:5px;padding:12px 14px;border:1px solid #d5e0bb26;border-radius:12px;background:#102018b8;backdrop-filter:blur(8px);min-height:43px}.spore{width:12px;height:17px;border-radius:60% 40% 55% 45%;display:block;transform:rotate(-25deg);background:#d6efad;box-shadow:0 0 11px #c9ef9a65}.spore:not(.full){background:#344638;box-shadow:none}.roots-panel{width:136px;padding:9px 12px 10px;border:1px solid #d5e0bb26;border-radius:12px;background:#102018b8;backdrop-filter:blur(8px)}.roots-label{display:flex;justify-content:space-between;color:#c5cdb3;font:10px 'DM Mono',monospace;letter-spacing:1.2px;margin-bottom:7px}.roots-label b{color:var(--lime);font-weight:500}.roots-track,.objective-track{width:100%;height:4px;background:#ffffff21;border-radius:9px;overflow:hidden}.roots-track span,.objective-track span{height:100%;display:block;width:0;background:#b9e491;border-radius:inherit;transition:width .25s}.objective{position:absolute;left:50%;transform:translateX(-50%);padding:10px 20px 11px;background:#102018ba;border:1px solid #d5e0bb26;border-radius:12px;min-width:145px;text-align:center;backdrop-filter:blur(9px)}.objective-eyebrow{display:block;font:9px 'DM Mono',monospace;letter-spacing:1.5px;color:#b1b99d}.objective-main{margin:1px 0 8px;font-size:19px;font-weight:700;line-height:1}.objective-main b{color:#d1f2a9}.objective-main span{color:#87917e;font-size:12px}.objective-track{height:3px}.hud-right{align-items:flex-start}.minimap-wrap{width:104px;height:78px;border:1px solid #d9e8bc5c;border-radius:8px;overflow:hidden;background:#1a3022;box-shadow:0 6px 24px #0005}.hud-buttons{display:flex;gap:7px;pointer-events:auto}.icon-btn{width:40px;height:40px;border-radius:11px;background:#102018c9;border:1px solid #d5e0bb30;display:grid;place-items:center;cursor:pointer;transition:background .15s,transform .15s}.icon-btn:hover{background:#334831}.icon-btn:active{transform:scale(.92)}.icon-btn svg{width:20px;height:20px;fill:#dce7c9}.icon-sound-off{display:none}.muted .icon-sound-on{display:none}.muted .icon-sound-off{display:block}.toast{position:absolute;top:82px;left:50%;transform:translate(-50%,-10px);padding:9px 16px;border:1px solid #d1ec9e55;border-radius:7px;background:#172a1ee8;color:#dcf4b9;font:11px 'DM Mono',monospace;letter-spacing:1px;opacity:0;transition:.3s;pointer-events:none;white-space:nowrap}.toast.show{opacity:1;transform:translate(-50%,0)}.compass{position:absolute;top:118px;left:50%;transform:translateX(-50%);display:flex;align-items:center;gap:6px;opacity:.72;font:9px 'DM Mono',monospace;letter-spacing:1px;color:#ede2bb;pointer-events:none}.compass-arrow{width:8px;height:8px;border-top:2px solid #e8dfb5;border-right:2px solid #e8dfb5;transform:rotate(-45deg)}#controls{position:absolute;inset:0;z-index:3;pointer-events:none}.joystick{position:absolute;left:max(26px,env(safe-area-inset-left));bottom:max(28px,env(safe-area-inset-bottom));width:146px;height:146px;pointer-events:auto;touch-action:none}.joystick-ring{position:absolute;inset:0;border-radius:50%;background:#10201856;border:1px solid #dbe8c