ace;letter-spacing:.3px;white-space:nowrap;pointer-events:none}.key-hints b{color:#e1e5c4;background:#1c2a20d9;border:1px solid #ffffff24;border-radius:4px;padding:3px 5px;margin-right:4px;font-weight:400}.overlay{position:absolute;inset:0;z-index:5;display:none}.overlay.visible{display:flex}.menu{align-items:center;justify-content:flex-start;background:linear-gradient(90deg,rgba(9,17,12,.98) 0%,rgba(9,17,12,.94) 34%,rgba(9,17,12,.64) 61%,rgba(9,17,12,.08) 100%),linear-gradient(0deg,#0b160ec9,transparent 35%),radial-gradient(ellipse at 75% 40%,#75904845,transparent 48%);overflow:auto}.menu:before{content:'';position:absolute;inset:0;background:radial-gradient(ellipse at 78% 84%,#bf8e4d24,transparent 28%),linear-gradient(130deg,transparent 52%,#d7e1ad08 52.15%,transparent 52.5%);pointer-events:none}.menu-grain{position:absolute;inset:0;opacity:.12;background-image:url("data:image/svg+xml,%3Csvg viewBox='0 0 180 180' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='.82' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='.23'/%3E%3C/svg%3E");pointer-events:none}.menu-panel{position:relative;z-index:1;width:min(510px,47vw);min-width:410px;max-height:100%;overflow:auto;margin-left:clamp(34px,8.5vw,142px);padding:26px 0 20px;scrollbar-width:none}.menu-panel::-webkit-scrollbar{display:none}.menu-crest{width:160px;height:130px;margin:0 auto 3px;filter:drop-shadow(0 13px 15px #0007);animation:crestFloat 4s ease-in-out infinite}.menu-crest svg{width:100%;height:100%;overflow:visible}.crest-roots{stroke-width:3}.crest-fireflies circle{animation:firefly 2s ease-in-out infinite alternate}.crest-fireflies circle:nth-child(2){animation-delay:.5s}.crest-fireflies circle:nth-child(3){animation-delay:1s}.eyebrow,.modal-eyebrow{color:#c1d69b;text-align:center;font:10px 'DM Mono',monospace;letter-spacing:3.3px}.menu h1{font:700 clamp(38px,5vw,61px)/.99 Unbounded