4px Unbounded,Manrope,sans-serif;letter-spacing:-1.5px;margin:11px 0 7px;color:#ecedcf}.modal>p{margin:0;color:#aeb69e;font-size:12px}.modal-actions{display:grid;gap:9px;margin-top:24px}.primary-btn.compact{min-height:47px}.ghost-btn{height:39px;border:1px solid #d5e4bd2d;background:#ffffff05;color:#c3cbb3;border-radius:7px;font:10px 'DM Mono',monospace;letter-spacing:1.2px;cursor:pointer}.ghost-btn:hover{background:#ffffff12}.pause-stats{display:flex;justify-content:center;gap:18px;padding-top:21px;margin-top:20px;border-top:1px solid #ffffff19;color:#8f9b85;font:9px 'DM Mono',monospace}.pause-stats b{display:block;margin-top:6px;color:#e4e6c8;font-size:13px;font-weight:500}.result-modal{padding-top:27px}.result-sigil{width:63px;height:63px;margin:0 auto 15px;border-radius:50%;display:grid;place-items:center;background:#cbe9a41b;border:1px solid #d8f1b360;color:#d8f5af;font-size:32px}.result-sigil:before{content:'✦'}.result-modal h2{font-size:29px}.result-stats{display:flex;justify-content:center;gap:0;margin-top:23px;padding:17px 0;border-top:1px solid #ffffff19;border-bottom:1px solid #ffffff19}.result-stats span{flex:1;display:grid;gap:5px;border-right:1px solid #ffffff16}.result-stats span:last-child{border:0}.result-stats b{font:600 19px Unbounded,sans-serif;color:#d7eca9}.result-stats small{font:8px 'DM Mono',monospace;letter-spacing:1px;color:#909b84}.rotate-hint{display:none;position:absolute;z-index:8;inset:0;align-items:center;justify-content:center;padding:35px;background:#101b14ed;text-align:center;color:#d7e8ba;font-size:14px}.rotate-hint span{max-width:280px}.menu .touch-note{display:none}@keyframes crestFloat{50%{transform:translateY(-5px)}}@keyframes firefly{to{opacity:.25;filter:drop-shadow(0 0 4px #c9ff9a)}}
@media (max-width:700px){.menu{justify-content:center;background:linear-gradient(90deg,rgba(9,17,12,.97),rgba(9,17,12,.84)),radial-gradient(ellipse at 70% 20%,#75904835,transparent 60%)}.menu-panel{width:min(480px,calc(100vw - 52px));min-width:0;margin:0 auto;padding:15px 0 16px}.menu-crest{width:125px;height:96px;margin-bottom:0}.menu h1{font-size:clamp(37px,9vw,52px);margin-top:5px}.tagline{font-size:12px}.ability-list{margin:15px 0 15px;gap:9px}.ability-icon{width:34px;height:34px;border-radius:9px}.ability-icon svg{width:21px;height:21px}.ability b{font-size:11px}.ability div span{font-size:9.5px}.primary-btn{min-height:46px}.menu-foot{font-size:7.5px}.menu-corner{display:none}.hud-top{left:10px;right:10px;top:max(10px,env(safe-area-inset-top))}.hud-left{gap:7px}.health{padding:9px 10px;gap:4px;min-height:36px;border-radius:10px}.spore{width:10px;height:14px}.roots-panel{width:105px;padding:7px 9px;border-radius:10px}.roots-label{font-size:8px;margin-bottom:5px}.objective{min-width:100px;padding:7px 11px 8px;border-radius:9px}.objective-eyebrow{font-size:7px;letter-spacing:1px}.objective-main{font-size:16px;margin:2px 0 6px}.minimap-wrap{width:72px;height:54px;border-radius:6px}.hud-right{gap:5px}.hud-buttons{gap:4px}.icon-btn{width:32px;height:32px;border-radius:8px}.icon-btn svg{width:16px;height:16px}.toast{top:68px;font-size:9px}.compass{top:77px;font-size:8px}.joystick{width:120px;height:120px;left:max(17px,env(safe-area-inset-left));bottom:max(18px,env(safe-area-inset-bottom))}.joystick-knob{width:53px;height:53px}.actions{right:max(14px,env(safe-area-inset-right));bottom:max(18px,env(safe-area-inset-bottom));gap:10px}.action-btn{width:69px;height:69px}.action-btn.poison{width:61px;height:61px}.action-btn svg{width:28px;height:28px}.action-btn.poison svg{width:27px;height:27px}.action-copy b{font-size:9px}.action-copy small{display:none}.key-hints{display:none}.modal{padding:30px 25px 23px}.pause-stats{gap:12px;font-size:8px}}
@media (max-width:500px) and (orientation:portrait){.rotate-hint.show{display:flex}.menu-panel{max-height:calc(100% - 18px);overflow-y:auto}.menu-crest{height:84px;width:110px}.menu h1{font-size:37px}.ability-list{margin:12px 0;gap:8px}.ability div span{font-size:9px}.menu-foot{margin-top:8px}.menu{background:linear-gradient(90deg,rgba(9,17,12,.99),rgba(9,17,12,.92)),radial-gradient(ellipse at 70% 20%,#75904835,transparent 60%)}}
@media (max-height:680px) and (min-width:701px){.menu-panel{width:410px;margin-left:7vw;padding:8px 0}.menu-crest{width:115px;height:90px}.menu h1{font-size:43px;margin:4px 0}.tagline{font-size:11px}.ability-list{gap:7px;margin:12px 0}.ability-icon{width:31px;height:31px}.ability b{font-size:10px}.ability div span{font-size:9px}.primary-btn{min-height:42px}.menu-foot{margin-top:8px}}

(() => {
  'use strict';
  const canvas = document.getElementById('game');
  const ctx = canvas.getContext('2d');
  const minimap = document.getElementById('minimap');
  const mapCtx = minimap.getContext('2d');
  const $ = (id) => document.getElementById(id);
  const ui = {hud:$('hud'),controls:$('controls'),menu:$('menu'),pause:$('pause'),result:$('result'),start:$('startBtn'),pauseBtn:$('pauseBtn'),resume:$('resumeBtn'),restart:$('restartBtn'),menuBtn:$('menuBtn'),again:$('againBtn'),resultMenu:$('resultMenuBtn'),strike:$('strikeBtn'),poison:$('poisonBtn'),sound:$('soundBtn'),health:$('health'),rootFill:$('rootFill'),rootLevel:$('rootLevel'),captured:$('capturedCount'),objective:$('objectiveFill'),toast:$('toast'),compass:$('compass'),rotate:$('rotateHint')};
  const WORLD = {w:2300,h:1650};
  const colors = {ground:'#263b28',ground2:'#2b402b',canopy:'#3c5635',canopy2:'#52633a',bark:'#66543b',moss:'#71834b',root:'#bbd790',cream:'#f2e7cb'};
  let W=innerWidth,H=innerHeight,DPR=1, state='menu', last=0, elapsed=0, toastTimer=0, soundOn=false, audio=null;
  let camera={x:0,y:0}, player, enemies=[], shrines=[], trees=[], plants=[], particles=[], floating=[], score=0,kills=0,captured=0, strikeCD=0,poisonCD=0,poisonTime=0,damageFlash=0, keys={}, joy={x:0,y:0,active:false}, attackPulse=0, worldSeed=32198;
  const rand=(min,max)=>min+Math.random()*(max-min);
  const clamp=(v,min,max)=>Math.max(min,Math.min(max,v));
  const dist=(a,b)=>Math.hypot(a.x-b.x,a.y-b.y);
  const resize=()=>{W=innerWidth;H=innerHeight;DPR=Math.min(devicePixelRatio||1,2);canvas.width=Math.floor(W*DPR);canvas.height=Math.floor(H*DPR);canvas.style.width=W+'px';canvas.style.height=H+'px';ctx.setTransform(DPR,0,0,DPR,0,0);};
  addEventListener('resize',resize,{passive:true});resize();
  function newGame(){
    score=0;kills=0;captured=0;elapsed=0;strikeCD=0;poisonCD=0;poisonTime=0;damageFlash=0;attackPulse=0;particles=[];floating=[];worldSeed=Date.now();
    player={x:WORLD.w/2,y:WORLD.h/2,faceX:1,faceY:0,r:16,hp:3,invuln:0,rootGrowth:0};
    shrines=[];const shrinePos=[[410,355],[1135,285],[1870,405],[355,1175],[1130,1350],[1920,1180],[1480,820]];
    shrinePos.forEach((p,i)=>shrines.push({x:p[0],y:p[1],r:32,id:i,progress:0,captured:false,glow:rand(0,6),type:i%3}));
    const kinds=['wolf','hare','bear','elk'];
    enemies=[];const enemyPos=[[590,400],[930,410],[1460,330],[2030,600],[620,900],[1000,1110],[1640,1120],[2030,1330],[1320,610],[300,760],[1790,850],[810,1410]];
    enemyPos.forEach((p,i)=>{const kind=kinds[i%4];const stats={wolf:[27,71],hare:[17,87],bear:[43,42],elk:[34,57]}[kind];enemies.push({x:p[0],y:p[1],homeX:p[0],homeY:p[1],kind,r:stats[0],speed:stats[1],hp:1,poisoned:0,dead:false,attack:rand(0,1.8),wander:rand(0,4),vx:0,vy:0,seed:rand(0,9),notice:false});});
    trees=[];plants=[];for(let i=0;i<190;i++){let x=rand(45,WORLD.w-45),y=rand(45,WORLD.h-45);if(Math.hypot(x-player.x,y-player.y)>85)trees.push({x,y,r:rand(13,28),variant:Math.floor(rand(0,5)),shade:rand(-.1,.12)});}
    for(let i=0;i<520;i++)plants.push({x:rand(0,WORLD.w),y:rand(0,WORLD.h),type:Math.floor(rand(0,5)),scale:rand(.6,1.4),phase:rand(0,8)});
    camera.x=clamp(player.x-W/2,0,WORLD.w-W);camera.y=clamp(player.y-H/2,0,WORLD.h-H);
    updateHUD();
  }
  function showToast(text){ui.toast.textContent=text;ui.toast.classList.add('show');toastTimer=2;}
  function setState(next){state=next;ui.menu.classList.toggle('visible',next==='menu');ui.pause.classList.toggle('visible',next==='paused');ui.result.classList.toggle('visible',next==='won'||next==='lost');ui.hud.classList.toggle('hidden',next==='menu');ui.controls.classList.toggle('hidden',next==='menu'||next==='paused'||next==='won'||next==='lost');if(next==='paused'){ $('pauseScore').textContent=score;$('pauseKills').textContent=kills;$('pauseShrines').textContent=`${captured}/7`;}}
  function start(){newGame();setState('playing');last=performance.now();showToast('НАЙДИ ДРЕВНИЕ ПНИ');}
  function fmtTime(seconds){return `${Math.floor(seconds/60)}:${String(Math.floor(seconds%60)).padStart(2,'0')}`;}
  function finish(won){if(state!=='playing')return;setState(won?'won':'lost');$('resultEyebrow').textContent=won?'ЛЕС ПРИНАДЛЕЖИТ ТЕБЕ':'ЛЕС ОТБРОСИЛ ТЕБЯ';$('resultTitle').textContent=won?'ЛЕС ТВОЙ':'ПОСЛЕДНЯЯ СПОРА';$('resultText').textContent=won?'Каждый корень дотянулся до сердца чащи.':'Лес велик. Но мицелий умеет ждать.';$('resultScore').textContent=score;$('resultKills').textContent=kills;$('resultTime').textContent=fmtTime(elapsed);$('resultSigil').style.color=won?'#d8f5af':'#e9ad83';}
  function updateHUD(){ui.captured.textContent=captured;ui.objective.style.width=`${captured/7*100}%`;const growth=clamp(elapsed/100+kills*.045,0,1);player.rootGrowth=growth;ui.rootFill.style.width=`${Math.max(5,growth*100)}%`;ui.rootLevel.textContent=`УР. ${Math.min(9,1+Math.floor(growth*8))}`;ui.health.innerHTML=Array.from({length:3},(_,i)=>`<span class="spore ${i<player.hp?'full':''}"></span>`).join('');setCooldown(ui.strike,strikeCD/3.2);setCooldown(ui.poison,poisonCD/12);}
  function setCooldown(button,value){button.classList.toggle('cooling',value>0);button.querySelector('.cooldown').style.transform=`scaleY(${clamp(value,0,1)})`;}
  function playSound(freq=220,duration=.08,type='sine'){if(!soundOn)return;try{audio=audio||new (window.AudioContext||window.webkitAudioContext)();const osc=audio.createOscillator(),gain=audio.createGain();osc.type=type;osc.frequency.value=freq;gain.gain.setValueAtTime(.055,audio.currentTime);gain.gain.exponentialRampToValueAtTime(.001,audio.currentTime+duration);osc.connect(gain);gain.connect(audio.destination);osc.start();osc.stop(audio.currentTime+duration);}catch(_){}}
  function burst(x,y,color,n=12){for(let i=0;i<n;i++){const a=rand(0,Math.PI*2),s=rand(25,115);particles.push({x,y,vx:Math.cos(a)*s,vy:Math.sin(a)*s,life:rand(.35,.8),max:.8,size:rand(2,5),color});}}
  function textPop(x,y,text,color='#e9efba'){floating.push({x,y,text,color,life:1.15});}
  function killEnemy(e,kind='strike'){
