  function setJoy(event){const rect=$('joystick').getBoundingClientRect(),cx=rect.left+rect.width/2,cy=rect.top+rect.height/2,dx=event.clientX-cx,dy=event.clientY-cy,max=rect.width*.36,n=Math.max(1,Math.hypot(dx,dy));joy.x=dx/n*Math.min(1,n/max);joy.y=dy/n*Math.min(1,n/max);const lim=rect.width*.27;$('joystickKnob').style.transform=`translate(calc(-50% + ${joy.x*lim}px),calc(-50% + ${joy.y*lim}px))`;}
